from textlesson import build
S=dict(cls=6,subj="social-science",subj_file="social-science")
build(dict(S,ch="locating-places-on-the-earth",topic="reading-maps",name_en="Reading maps",name_ta="வரைபடம் படித்தல்",
 objectives=["Use direction, scale and symbols on a map","Find a place using the map key"],
 story=("The treasure map","Hari drew a map of his school ground to hide a treasure. He marked the gate, the well and the big tree, and drew an arrow showing north.\n\"Walk ten steps east from the gate,\" he wrote.\nHis friend followed the map and found the treasure."),
 explain=["A map is a drawing of a place as seen from above. Maps use four main directions: north, south, east and west, shown by a direction arrow.","The scale tells how much smaller the map is than the real place, for example 1 centimetre stands for 1 kilometre. Symbols and colours show things such as roads, rivers and schools, and the key or legend explains them.","Maps of the whole earth are in atlases. A globe is a small model of the earth, and a map is flat."],
 terms=["map","scale","symbol","key","atlas"],
 narr=[("A map is a drawing of a place seen from above. It uses the four directions.","directions"),("The scale shows how much smaller the map is than the real place.","scale"),("Symbols and colours show roads, rivers and schools. The key explains them.","symbols and key"),("An atlas is a book of maps.","atlas")],
 ex=("A map has scale 1 cm = 2 km. Two towns are 5 cm apart on the map. How far apart are they?",[("Each centimetre stands for 2 kilometres.","This is the scale."),("There are 5 centimetres, so multiply 5 by 2.","5 times 2 is 10."),("So the towns are 10 kilometres apart.","Distance equals map length times scale.")]),
 tb=("A friend asks why a map has a key. How will you explain?",["The key tells what each symbol and colour means.","Without it we cannot read the map."],["Thinking symbols explain themselves."]),
 summary=["A map shows a place from above with directions, scale and symbols.","The key explains the symbols.","An atlas is a book of maps."],
 q=[("mcq",1,"r1-dir","How many main directions are there?","four",[("two","There are north, south, east and west."),("six","There are four main ones.")],"North, south, east and west."),
    ("tf",1,"r1-arrow","A direction arrow on a map shows north.",True,"True."),
    ("mcq",2,"r2-scale","The scale of a map tells","how much smaller the map is than the real place",[("the name of the map","It gives size relation."),("the colour of roads","That is the key.")],"It links map distance to real distance."),
    ("tf",2,"r2-key","The key explains the symbols on a map.",True,"True."),
    ("mcq",3,"r3-calc","On a map with 1 cm = 3 km, 4 cm is","12 km",[("7 km","Multiply, do not add."),("1 km","Multiply 4 by 3.")],"4 times 3 is 12."),
    ("short",3,"r3-book","What do we call a book of maps?",["atlas","an atlas"],"A book of maps is an atlas."),
    ("mcq",4,"r4-view","A map is drawn as if seen from","above",[("the side","That is a side view."),("below","That is not how maps are drawn.")],"It is a top view."),
    ("tf",4,"r4-globe","A globe is a model of the earth.",True,"True.")]))
build(dict(S,ch="india-that-is-bharat",topic="states-and-neighbours-of-india",name_en="States and neighbours of India",name_ta="இந்திய மாநிலங்களும் அண்டை நாடுகளும்",
 objectives=["Say that India has states and union territories","Name some neighbouring countries"],
 story=("The big map","In class a huge map of India hung on the wall. Latha pointed at her state, Tamil Nadu, in the south.\n\"Which countries are next to us?\" asked the teacher.\n\"Pakistan, Nepal, China, Bhutan, Bangladesh and Myanmar are on land,\" said Latha, \"and Sri Lanka is across the sea.\""),
 explain=["India is divided into states and union territories. Each state has its own government and capital, and many have their own language. Delhi is the capital of India.","India has neighbours on land: Pakistan and Afghanistan in the north-west, China, Nepal and Bhutan in the north, and Bangladesh and Myanmar in the east.","Sri Lanka and the Maldives are island neighbours in the Indian Ocean. India has a long coastline. The Himalayas lie in the north and the Indian Ocean in the south."],
 terms=["state","union territory","capital","neighbour"],
 narr=[("India is divided into states and union territories. Delhi is the capital of India.","states and capital"),("Pakistan, China, Nepal, Bhutan, Bangladesh and Myanmar share a land border with India.","land neighbours"),("Sri Lanka and the Maldives are island neighbours in the Indian Ocean.","island neighbours"),("The Himalayas are in the north and the Indian Ocean is in the south.","Himalayas and ocean")],
 ex=("Which neighbour of India is an island country to the south?",[("The countries on land touch India's border.","Islands do not."),("Sri Lanka lies across the sea in the south.","It is an island."),("So Sri Lanka is the island neighbour. The Maldives is another.","Both are in the Indian Ocean.")]),
 tb=("A friend says Sri Lanka shares a land border with India. How will you correct this?",["Sri Lanka is an island separated from India by the sea.","Land neighbours include Nepal and Bangladesh."],["Thinking all neighbours share a land border."]),
 summary=["India has states and union territories; Delhi is the capital.","Land neighbours include Pakistan, China, Nepal, Bhutan, Bangladesh and Myanmar.","Sri Lanka and the Maldives are island neighbours."],
 q=[("mcq",1,"r1-cap","The capital of India is","Delhi",[("Chennai","Chennai is the capital of Tamil Nadu."),("Mumbai","Mumbai is the capital of Maharashtra.")],"New Delhi is the capital."),
    ("tf",1,"r1-state","India is divided into states and union territories.",True,"True."),
    ("mcq",2,"r2-land","Which country shares a land border with India?","Nepal",[("Sri Lanka","It is an island."),("Maldives","It is an island.")],"Nepal is in the north."),
    ("tf",2,"r2-sl","Sri Lanka is an island neighbour of India.",True,"True."),
    ("mcq",3,"r3-north","Which mountains lie in the north of India?","Himalayas",[("Western Ghats","They are in the west."),("Aravalli","They are in the north-west but smaller.")],"The Himalayas are in the north."),
    ("short",3,"r3-neigh","Name one neighbour of India.",["nepal","bhutan","china","pakistan","bangladesh","myanmar","sri lanka","maldives","afghanistan"],"Nepal, Bhutan and others are neighbours."),
    ("mcq",4,"r4-ocean","The ocean to the south of India is the","Indian Ocean",[("Pacific Ocean","It is far from India."),("Arctic Ocean","It is near the North Pole.")],"India's southern coast meets the Indian Ocean."),
    ("tf",4,"r4-coast","India has a long coastline.",True,"True.")]))
build(dict(S,ch="indias-cultural-roots",topic="festivals-and-traditions",name_en="Festivals and traditions",name_ta="திருவிழாக்களும் மரபுகளும்",
 objectives=["Name festivals of different regions","Say how festivals bring people together"],
 story=("Pongal at the neighbour's","On Pongal morning Meena's family cooked sweet rice in a new pot in the yard. Her friend Imran came with sweets for them.\nA month later, Meena's family went to Imran's house for Eid.\n\"Our festivals are different but our joy is the same,\" said Imran."),
 explain=["India has many festivals: Pongal, Diwali, Eid, Christmas, Onam, Holi, Baisakhi and Gurpurab. Many are linked to seasons, harvests, or great events in the lives of religious teachers.","Festivals bring families and neighbours together. People share food, wear new clothes, decorate homes and sing and dance.","Traditions such as folk dances, music and crafts are passed from older people to children. This is how our culture lives on."],
 terms=["festival","harvest","tradition","culture"],
 narr=[("India has many festivals like Pongal, Diwali, Eid and Christmas.","many festivals"),("Some festivals welcome the harvest. Others remember great people and events.","harvest and events"),("People share food and joy, and neighbours join each other's festivals.","sharing"),("Traditions are passed on from elders to children.","passing traditions")],
 ex=("Why is Pongal celebrated in Tamil Nadu in January?",[("It is the harvest festival after the crops are cut.","Farmers give thanks."),("People cook new rice and thank the Sun and cattle.","It is linked to farming."),("So Pongal is a festival of the harvest.","Many festivals link to nature.")]),
 tb=("A friend says festivals are only for one community. What will you say?",["Many festivals are enjoyed by neighbours of all communities.","Sharing them shows our unity."],["Thinking festivals divide people."]),
 summary=["India celebrates many festivals.","Some mark harvests or great events.","Festivals and traditions bring people together."],
 q=[("mcq",1,"r1-pong","Pongal is a","harvest festival",[("school exam","It is a festival."),("sports day","It is a festival.")],"Farmers give thanks."),
    ("tf",1,"r1-many","India has many festivals.",True,"True."),
    ("mcq",2,"r2-share","Festivals bring people","together",[("far apart","They unite families."),("to fight","They bring joy.")],"People share food and joy."),
    ("tf",2,"r2-only","Only one community enjoys festivals in India.",False,"False. Neighbours share them."),
    ("mcq",3,"r3-trad","Traditions are","passed from elders to children",[("forgotten quickly","They are handed down."),("made by machines","People pass them on.")],"This keeps culture alive."),
    ("short",3,"r3-name","Name one festival of India.",["pongal","diwali","eid","christmas","onam","holi","baisakhi","deepavali","dussehra","navratri","ugadi","gurpurab"],"There are many festivals."),
    ("mcq",4,"r4-eid","Which festival is celebrated by Muslims after Ramzan?","Eid",[("Onam","Onam is a Kerala festival."),("Holi","Holi is a festival of colours.")],"Eid marks the end of Ramzan."),
    ("tf",4,"r4-dance","Folk dances are part of our traditions.",True,"True.")]))
build(dict(S,ch="grassroots-democracy-part-2-local-government-in-rural-areas",topic="the-gram-sabha",name_en="The Gram Sabha",name_ta="கிராம சபை",
 objectives=["Say what the Gram Sabha is","Say why every adult can take part"],
 story=("The village meeting","The drum was beaten in Meenapuram and everyone gathered under the banyan tree.\nThe panchayat president read out the money spent on the new well. An old woman asked, \"Why was the road not repaired?\"\nThe president noted her question and promised an answer."),
 explain=["The Gram Sabha is a meeting of all the adult voters of a village. Every adult man and woman who has a vote is a member and can speak.","In the meeting the panchayat tells the people how money was spent and what work is planned. People can ask questions and suggest what the village needs, such as water, roads or a school.","The Gram Sabha makes the panchayat answerable to the people. It is a true example of people taking part in governing themselves."],
 terms=["Gram Sabha","adult voters","panchayat","accountable"],
 narr=[("The Gram Sabha is a meeting of all the adult voters of a village.","all adult voters"),("The panchayat tells how money was spent and what work is planned.","accounts and plans"),("Anyone can ask questions and suggest what the village needs.","questions and suggestions"),("This makes the panchayat answerable to the people.","answerable")],
 ex=("Why should women also attend the Gram Sabha?",[("Every adult voter is a member, including women.","They have the same rights."),("Women know village needs such as water and health.","Their ideas help."),("So their presence makes decisions fairer.","The village is for everyone.")]),
 tb=("A friend says only the panchayat president takes decisions in a village. What will you say?",["The Gram Sabha, with all adult voters, can ask questions and give suggestions.","The panchayat must answer to it."],["Thinking one person governs the village."]),
 summary=["The Gram Sabha is a meeting of all adult voters of a village.","It discusses money, plans and needs.","It keeps the panchayat answerable."],
 q=[("mcq",1,"r1-who","Who are the members of the Gram Sabha?","all adult voters of the village",[("only the president","Everyone with a vote is a member."),("only teachers","Everyone with a vote is a member.")],"It is open to all adult voters."),
    ("tf",1,"r1-meet","The Gram Sabha is a meeting of village people.",True,"True."),
    ("mcq",2,"r2-money","In the Gram Sabha the panchayat tells people","how money was spent",[("a story","It reports its work."),("a film plot","It reports its work.")],"It explains accounts and plans."),
    ("tf",2,"r2-ask","People may ask questions in the Gram Sabha.",True,"True."),
    ("mcq",3,"r3-ans","The Gram Sabha makes the panchayat","answerable to the people",[("secret","It makes it open."),("stronger than law","It must answer to people.")],"People can question it."),
    ("short",3,"r3-need","Name one need of a village that people may raise.",["water","road","school","health","electricity","well","drains","toilets","roads"],"Water, roads and schools are common needs."),
    ("mcq",4,"r4-where","A Gram Sabha usually meets","in the village",[("in a far city","It meets in the village."),("in a court","It meets in the village.")],"Villagers gather in a common place."),
    ("tf",4,"r4-part","Taking part in the Gram Sabha is a way to govern ourselves.",True,"True.")]))
